gaC0(){return"\u0645\u0633\u0627\u0621 \u0627\u0644\u062e\u064a\u0631 \u0633\u064a\u062f\u0627\u062a\u064a \u0648\u0633\u0627\u062f\u062a\u064a\u060c \u0645\u0639\u0643\u0645 \u0627\u0644\u0645\u0639\u0644\u0651\u0642 \u0633\u0639\u064a\u062f. \u0646\u062d\u0646 \u0639\u0644\u0649 \u0627\u0644\u0647\u0648\u0627\u0621 \u0645\u0628\u0627\u0634\u0631\u0629!"},
gaC1(){return"\u0645\u0633\u0627\u0621 \u0627\u0644\u062e\u064a\u0631 \u0644\u0643\u0644 \u0645\u0646 \u064a\u062a\u0627\u0628\u0639\u0646\u0627\u060c \u0645\u0639\u0643\u0645 \u0633\u0639\u064a\u062f. \u0645\u0628\u0627\u0631\u0627\u0629 \u0645\u062b\u064a\u0631\u0629 \u0628\u0627\u0646\u062a\u0638\u0627\u0631\u0646\u0627!"},
gaC2(){return"\u0645\u0633\u0627\u0621 \u0627\u0644\u062e\u064a\u0631 \u064a\u0627 \u0639\u0634\u0651\u0627\u0642 \u0643\u0631\u0629 \u0627\u0644\u0642\u062f\u0645\u060c \u0645\u0639\u0643\u0645 \u0633\u0639\u064a\u062f. \u062d\u0627\u0646 \u0648\u0642\u062a \u0627\u0644\u0645\u0628\u0627\u0631\u0627\u0629!"},
gaCb(){return"\u0627\u0644\u0644\u064a\u0644\u0629 \u0645\u0628\u0627\u0631\u0627\u0629 \u0641\u064a \u0627\u0644\u062f\u0648\u0631\u064a\u060c \u0648\u0643\u0644 \u0646\u0642\u0637\u0629 \u0644\u0647\u0627 \u0642\u064a\u0645\u062a\u0647\u0627."},
gaCc(){return"\u0623\u0633\u0628\u0648\u0639 \u062c\u062f\u064a\u062f \u0641\u064a \u0627\u0644\u062f\u0648\u0631\u064a\u060c \u0648\u0645\u0639\u0631\u0643\u0629 \u062c\u062f\u064a\u062f\u0629."},
gaC8(){return"\u0627\u0644\u0623\u0646\u0641\u0627\u0633 \u0645\u062d\u0628\u0648\u0633\u0629 \u0641\u064a \u0627\u0644\u0643\u0623\u0633\u060c \u0648\u0627\u0644\u062e\u0627\u0633\u0631 \u064a\u0646\u062a\u0647\u064a \u0645\u0634\u0648\u0627\u0631\u0647 \u0647\u0646\u0627."},
gaC9(){return"\u062d\u0645\u0627\u0633 \u0627\u0644\u0643\u0623\u0633! \u0627\u0644\u0641\u0627\u0626\u0632 \u0627\u0644\u0644\u064a\u0644\u0629 \u064a\u062a\u0623\u0647\u0644."},
gaCd(){return"\u0623\u0648\u0644 \u0645\u0628\u0627\u0631\u0627\u0629 \u0641\u064a \u0627\u0644\u0645\u0648\u0633\u0645! \u0627\u0644\u062c\u0645\u064a\u0639 \u064a\u0631\u064a\u062f \u0628\u062f\u0627\u064a\u0629 \u062c\u064a\u062f\u0629."},
gaCa(){return"\u0622\u062e\u0631 \u0645\u0628\u0627\u0631\u0627\u0629 \u0641\u064a \u0627\u0644\u0645\u0648\u0633\u0645! \u0643\u0644 \u0627\u0644\u062d\u0633\u0627\u0628\u0627\u062a \u062a\u064f\u063a\u0644\u0642 \u0627\u0644\u0644\u064a\u0644\u0629."},
gaC3(){return"\u0643\u0627\u0644\u0639\u0627\u062f\u0629\u060c \u0645\u0639\u064a \u0627\u0644\u0623\u0633\u062a\u0627\u0630 \u0643\u0645\u0627\u0644. \u0623\u0647\u0644\u0627\u064b \u0628\u0643 \u064a\u0627 \u0623\u0633\u062a\u0627\u0630!"},
gaC4(){return"\u0627\u0644\u0623\u0633\u062a\u0627\u0630 \u0643\u0645\u0627\u0644 \u0645\u0639\u0646\u0627 \u0627\u0644\u0644\u064a\u0644\u0629 \u0623\u064a\u0636\u0627\u064b \u0628\u062a\u062d\u0644\u064a\u0644\u0627\u062a\u0647. \u0645\u0633\u0627\u0621 \u0627\u0644\u062e\u064a\u0631 \u064a\u0627 \u0623\u0633\u062a\u0627\u0630!"},
gaCL(){return"\u0633\u0639\u064a\u062f \u0628\u0648\u062c\u0648\u062f\u064a \u064a\u0627 \u0633\u0639\u064a\u062f! \u0627\u0644\u0634\u0627\u064a \u062c\u0627\u0647\u0632\u060c \u0648\u0627\u0644\u0645\u0628\u0627\u0631\u0627\u0629 \u062c\u0627\u0647\u0632\u0629\u060c \u0648\u0623\u0646\u0627 \u062c\u0627\u0647\u0632!"},
gaCM(){return"\u0645\u0633\u0627\u0621 \u0627\u0644\u062e\u064a\u0631 \u064a\u0627 \u0633\u0639\u064a\u062f\u060c \u0648\u0645\u0633\u0627\u0621 \u0627\u0644\u062e\u064a\u0631 \u0644\u0643\u0644 \u0645\u062c\u0627\u0646\u064a\u0646 \u0643\u0631\u0629 \u0627\u0644\u0642\u062f\u0645 \u0623\u0645\u0627\u0645 \u0627\u0644\u0634\u0627\u0634\u0627\u062a!"},
gaCI(){return"\u0639\u0644\u0649 \u0627\u0644\u0648\u0631\u0642 \u0623\u0635\u062d\u0627\u0628 \u0627\u0644\u0623\u0631\u0636 \u0645\u062a\u0642\u062f\u0645\u0648\u0646\u060c \u0644\u0643\u0646 \u0627\u0644\u0643\u0631\u0629 \u0645\u0633\u062a\u062f\u064a\u0631\u0629 \u064a\u0627 \u0635\u062f\u064a\u0642\u064a\u060c \u0648\u0627\u0644\u0648\u0631\u0642 \u0644\u0627 \u064a\u0644\u0639\u0628!"},
gaCJ(){return"\u0623\u0635\u062d\u0627\u0628 \u0627\u0644\u0623\u0631\u0636 \u0647\u0645 \u0627\u0644\u0645\u0631\u0634\u062d\u0648\u0646\u060c \u0647\u0630\u0627 \u0623\u0643\u064a\u062f. \u0644\u0643\u0646 \u0625\u0646 \u0633\u062c\u0651\u0644 \u0627\u0644\u0636\u064a\u0648\u0641 \u0645\u0628\u0643\u0631\u0627\u064b\u060c \u0633\u062a\u0635\u0645\u062a \u0627\u0644\u0645\u062f\u0631\u062c\u0627\u062a!"},
gaCG(){return"\u0627\u0644\u0636\u064a\u0648\u0641 \u0623\u0641\u0636\u0644 \u0642\u0644\u064a\u0644\u0627\u064b \u0641\u064a \u0627\u0644\u062a\u0634\u0643\u064a\u0644\u0629 \u064a\u0627 \u0633\u0639\u064a\u062f. \u0639\u0644\u0649 \u0623\u0635\u062d\u0627\u0628 \u0627\u0644\u0623\u0631\u0636 \u0623\u0646 \u064a\u0633\u062a\u0645\u062f\u0651\u0648\u0627 \u0627\u0644\u0642\u0648\u0629 \u0645\u0646 \u0627\u0644\u0645\u062f\u0631\u062c\u0627\u062a \u0627\u0644\u0644\u064a\u0644\u0629!"},
gaCH(){return"\u064a\u0642\u0648\u0644\u0648\u0646 \u0625\u0646 \u0627\u0644\u0636\u064a\u0648\u0641 \u0647\u0645 \u0627\u0644\u0645\u0631\u0634\u062d\u0648\u0646\u060c \u0644\u0643\u0646 \u0647\u0630\u0627 \u0644\u064a\u0633 \u0645\u0643\u0627\u0646\u0627\u064b \u0633\u0647\u0644\u0627\u064b\u060c \u0623\u0635\u062d\u0627\u0628 \u0627\u0644\u0623\u0631\u0636 \u064a\u0635\u0628\u062d\u0648\u0646 \u0623\u0633\u0648\u062f\u0627\u064b \u0639\u0644\u0649 \u0645\u0644\u0639\u0628\u0647\u0645!"},
gaCE(){return"\u0627\u0644\u0641\u0631\u064a\u0642\u0627\u0646 \u0645\u062a\u0642\u0627\u0631\u0628\u0627\u0646 \u062c\u062f\u0627\u064b \u0644\u062f\u0631\u062c\u0629 \u0623\u0646 \u0627\u0644\u062a\u0641\u0627\u0635\u064a\u0644 \u0627\u0644\u0635\u063a\u064a\u0631\u0629 \u0633\u062a\u062d\u0633\u0645 \u0627\u0644\u0645\u0628\u0627\u0631\u0627\u0629\u060c \u0633\u062c\u0651\u0644\u0648\u0627 \u0643\u0644\u0627\u0645\u064a!"},
gaCF(){return"\u062a\u0628\u062f\u0648 \u0645\u0628\u0627\u0631\u0627\u0629 \u0645\u062a\u0643\u0627\u0641\u0626\u0629 \u064a\u0627 \u0633\u0639\u064a\u062f. \u0645\u0646 \u064a\u0633\u062c\u0651\u0644 \u0623\u0648\u0644\u0627\u064b \u064a\u062a\u0646\u0641\u0651\u0633\u060c \u0648\u0627\u0644\u0628\u0627\u0642\u064a \u062d\u0631\u0628 \u0623\u0639\u0635\u0627\u0628!"},
gaCD(){return"\u0625\u0646\u0647\u0627 \u0627\u0644\u0643\u0623\u0633 \u064a\u0627 \u0633\u0639\u064a\u062f\u060c \u0627\u0644\u0643\u0623\u0633! \u0647\u0646\u0627 \u0644\u0627 \u0642\u064a\u0645\u0629 \u0644\u0644\u0645\u0633\u062a\u0648\u0649 \u0648\u0644\u0627 \u0644\u0644\u062a\u0631\u062a\u064a\u0628\u060c \u0643\u0644 \u0634\u064a\u0621 \u0645\u0645\u0643\u0646 \u0627\u0644\u0644\u064a\u0644\u0629!"},
