gaCf(){return"\u0645\u0628\u0627\u0631\u0627\u0629 \u0627\u0644\u0630\u0647\u0627\u0628"},
gaCq(){return"\u0627\u0644\u0645\u062f\u0631\u062c\u0627\u062a \u062a\u0645\u062a\u0644\u0626\u060c \u0648\u0647\u0646\u0627\u0643 \u062d\u0645\u0627\u0633 \u0643\u0628\u064a\u0631 \u0641\u064a \u0627\u0644\u0645\u0644\u0639\u0628."},
